// Generated by `lecodes app sync` — regenerated on every sync, do not edit.
pluginManagement {
    repositories {
        google()
        mavenCentral()
        gradlePluginPortal()
    }
}
dependencyResolutionManagement {
    repositoriesMode.set(RepositoriesMode.FAIL_ON_PROJECT_REPOS)
    repositories {
        google()
        mavenCentral()
        // The LeCodes Android SDK: a fat AAR attached to GitHub Releases of the dist repo,
        // resolved straight off the release-download URL pattern (no Maven registry). The
        // content filter keeps Gradle from probing GitHub for every other coordinate.
        ivy {
            url = uri("https://github.com/letary/lecodes-android-sdk/releases/download")
            patternLayout { artifact("[revision]/[artifact]-[revision].[ext]") }
            metadataSources { artifact() }
            content { includeGroup("io.letary") }
        }
    }
}
rootProject.name = "aideal-autodiag-lecodes"
include(":app")
include(":lecodes-runtime")
include(":plugins:lecodes-browser")
include(":plugins:lecodes-camera")
include(":plugins:lecodes-audio-recorder")
include(":plugins:lecodes-speech")
